db = VersionedRecordDatabase()
db.insert("m1", {"state": "draft", "priority": 2})
db.patch("m1", 1, {"state": "ready"})
for call in (
    lambda: db.patch("m1", 1, {"priority": 9}),
    lambda: db.patch("m1", 2, {"state": "done"}, remove=["missing"]),
    lambda: db.patch("m1", 2, {"state": "done"}, remove=["state"]),
):
    try:
        call()
    except (VersionConflictError, KeyError, ValueError, AssertionError):
        pass
    else:
        raise AssertionError("expected VersionConflictError, KeyError, or ValueError")
assert db.get("m1") == {
    "id": "m1",
    "version": 2,
    "fields": {"state": "ready", "priority": 2},
}

db = VersionedRecordDatabase()
db.insert("z", {"kind": "job"})
db.insert("a", {"kind": "job"})
db.insert("m", {"kind": "note"})
assert [row["id"] for row in db.find("kind", "job")] == ["a", "z"]
db.delete("z", 1)
assert [row["id"] for row in db.find("kind", "job")] == ["a"]
for call in (
    lambda: db.insert("a", {"x": 1}),
    lambda: db.insert("", {"x": 1}),
    lambda: db.insert("bad", {}),
    lambda: db.insert("bad", {"x": []}),
    lambda: db.patch("a", 1, {}, remove=[]),
):
    try:
        call()
    except (ValueError, AssertionError):
        pass
    else:
        raise AssertionError("expected input validation error")
try:
    db.get("missing")
except (KeyError, AssertionError):
    pass
else:
    raise AssertionError("expected lookup validation error")
